def grade(marks):
    if marks >= 90:
        return "A"
    elif 75 <= marks < 90:
        return "B"
    elif 50 <= marks < 75:
        return "C"
    else:
        return "F"

# Test the function
print(grade(90))   # Should return "A"
print(grade(85))   # Should return "B"
print(grade(74))   # Should return "C"
print(grade(49))   # Should return "F"
```

