# Test the function
def test_word_counts():
    assert word_counts("Hello, world! Hello world.") == {'hello': 2, 'world': 1}
    assert word_counts("a a a") == {'a': 3}
    assert word_counts("Hello? World!") == {'hello': 1, 'world': 1}
    assert word_counts("") == {}
    assert word_counts("   ") == {}
```

