import sys

def celsius_to_fahrenheit(c):
    return round((9/5)*c + 32, 1)

def main():
    if len(sys.argv) != 2:
        print("Usage: python script.py <celsius>")
        return
    c = float(sys.argv[1])
    print(f"{celsius_to_fahrenheit(c):.1f}")

if __name__ == "__main__":
    main()
```

